cat > /app/ars.R <<'ARSEOF'
##############################################################################
## ars.R -- Adaptive Rejection Sampling (Gilks & Wild, 1992, JRSS-C 41:337-348)
##
## Public interface:
##   ars(density_function, domain, n = sample_count, ...)  -- the sampler
##   test()                                                -- formal test suite
##
## Design notes (consistent style throughout):
##   * plain functions (no OOP); lower_snake_case names; every auxiliary is
##     prefixed with "ars_" and implements one discrete task;
##   * the sampler state (abscissae x, h(x), h'(x), intersections z) is carried
##     in a single list called `hull`;
##   * everything is vectorised: hulls are evaluated and sampled for a whole
##     batch of candidate points at once.
##############################################################################


## ---------------------------------------------------------------------------
## 1. Input handling
## ---------------------------------------------------------------------------

## Coerce the user-supplied density into a vectorised function of one argument.
## Accepts a function, the name of a function ("dnorm"), a character string
## holding an expression in `x` ("exp(-x^2/2)"), or an unevaluated expression.
## Extra arguments in `...` are bound to the density.
ars_as_density <- function(density_function, ...) {
  extra <- list(...)

  if (is.function(density_function)) {
    f <- density_function
  } else if (is.character(density_function) && length(density_function) == 1L) {
    if (exists(density_function, mode = "function")) {
      f <- match.fun(density_function)
    } else {
      expr <- tryCatch(parse(text = density_function),
                       error = function(e)
                         stop("`density_function` is neither a function name nor a valid R expression",
                              call. = FALSE))
      f <- function(x) eval(expr[[1L]], list(x = x), parent.frame())
    }
  } else if (is.expression(density_function) || is.call(density_function) ||
             is.name(density_function)) {
    expr <- if (is.expression(density_function)) density_function[[1L]] else density_function
    f <- function(x) eval(expr, list(x = x), parent.frame())
  } else {
    stop("`density_function` must be a function, a function name, or an expression in x",
         call. = FALSE)
  }

  if (length(extra) == 0L) {
    dens <- function(x) as.numeric(f(x))
  } else {
    dens <- function(x) as.numeric(do.call(f, c(list(x), extra)))
  }
  dens
}

## Validate every user input; throws an informative error when something is
## wrong, otherwise returns the cleaned-up arguments.
ars_validate_inputs <- function(density_function, domain, n) {
  if (missing(density_function) || is.null(density_function))
    stop("`density_function` is required", call. = FALSE)

  if (missing(n) || is.null(n) || length(n) != 1L || !is.numeric(n) || !is.finite(n))
    stop("`n` must be a single finite number", call. = FALSE)
  if (n != as.integer(round(n)))
    stop("`n` must be a whole number, got ", n, call. = FALSE)
  n <- as.integer(round(n))
  if (n <= 0L)
    stop("`n` must be a positive integer, got ", n, call. = FALSE)

  if (is.null(domain)) domain <- c(-Inf, Inf)
  if (!is.numeric(domain) || length(domain) != 2L)
    stop("`domain` must be a numeric vector of length 2, e.g. c(-Inf, Inf)", call. = FALSE)
  if (any(is.na(domain)))
    stop("`domain` must not contain NA/NaN", call. = FALSE)
  if (domain[1L] >= domain[2L])
    stop("`domain` must satisfy domain[1] < domain[2], got (",
         domain[1L], ", ", domain[2L], ")", call. = FALSE)

  list(domain = as.numeric(domain), n = n)
}

## Log density, guarded against negative / non-finite densities.
ars_make_log_density <- function(dens) {
  function(x) {
    fx <- dens(x)
    if (length(fx) != length(x))
      stop("`density_function` is not vectorised: it must return one value per input value",
           call. = FALSE)
    if (any(is.na(fx)))
      stop("`density_function` returned NA/NaN", call. = FALSE)
    if (any(fx < 0))
      stop("`density_function` returned a negative value; a density must be non-negative",
           call. = FALSE)
    log(fx)
  }
}

## ---------------------------------------------------------------------------
## 2. Numerical derivative of the log density
## ---------------------------------------------------------------------------

## Vectorised central (or one-sided near a boundary) finite difference of h.
ars_derivative <- function(h, x, domain) {
  lo <- domain[1L]; hi <- domain[2L]
  eps <- pmax(1e-7, 1e-7 * abs(x))
  span <- min(hi - lo, Inf)
  eps <- pmin(eps, span / 4)

  left  <- pmax(x - eps, lo + eps / 8)
  right <- pmin(x + eps, hi - eps / 8)
  left  <- pmin(left, x)
  right <- pmax(right, x)

  hl <- h(left)
  hr <- h(right)
  d  <- (hr - hl) / (right - left)
  d[!is.finite(d)] <- NA_real_
  d
}

## ---------------------------------------------------------------------------
## 3. Hull construction
## ---------------------------------------------------------------------------

## Tangent intersection points z_j between successive abscissae, plus the
## domain boundaries (Gilks & Wild eq. 1).
ars_intersections <- function(x, hx, hpx, domain) {
  k <- length(x)
  z <- numeric(k + 1L)
  z[1L] <- domain[1L]
  z[k + 1L] <- domain[2L]
  if (k >= 2L) {
    j <- seq_len(k - 1L)
    dd <- hpx[j] - hpx[j + 1L]
    num <- hx[j + 1L] - hx[j] - x[j + 1L] * hpx[j + 1L] + x[j] * hpx[j]
    zj <- num / dd
    flat <- !is.finite(zj) | abs(dd) < 1e-12
    zj[flat] <- (x[j] + x[j + 1L])[flat] / 2   # parallel tangents: use midpoint
    ## numerical safety: z_j must lie between its two abscissae
    zj <- pmin(pmax(zj, x[j]), x[j + 1L])
    z[j + 1L] <- zj
  }
  z
}

## Build / rebuild the hull object from a set of abscissae.
ars_build_hull <- function(h, x, domain, hx = NULL, hpx = NULL) {
  ord <- order(x)
  x <- x[ord]
  if (!is.null(hx))  hx  <- hx[ord]
  if (!is.null(hpx)) hpx <- hpx[ord]

  keep <- c(TRUE, diff(x) > 1e-12)
  x <- x[keep]
  if (!is.null(hx))  hx  <- hx[keep]
  if (!is.null(hpx)) hpx <- hpx[keep]

  if (is.null(hx))  hx  <- h(x)
  if (is.null(hpx)) hpx <- ars_derivative(h, x, domain)

  if (any(!is.finite(hx)) || any(!is.finite(hpx)))
    stop("could not evaluate the log density or its derivative at the starting points; ",
         "check `domain` and `density_function`", call. = FALSE)
  if (length(x) < 2L)
    stop("at least two distinct starting abscissae are required", call. = FALSE)

  ars_check_log_concavity(x, hx, hpx)

  hull <- list(x = x, hx = hx, hpx = hpx, domain = domain)
  hull$z <- ars_intersections(x, hx, hpx, domain)
  hull <- ars_segment_weights(hull)
  hull
}

## Log-concavity check on the abscissae: h' must be non-increasing in x.
ars_check_log_concavity <- function(x, hx, hpx, tol = 1e-6) {
  if (length(x) < 2L) return(invisible(TRUE))
  d <- diff(hpx)
  scale <- pmax(1, abs(hpx[-length(hpx)]), abs(hpx[-1L]))
  bad <- which(d > tol * scale)
  if (length(bad) > 0L) {
    j <- bad[1L]
    stop("the supplied density does not appear to be log-concave: ",
         "h'(", format(x[j], digits = 6), ") = ", format(hpx[j], digits = 6),
         " < h'(", format(x[j + 1L], digits = 6), ") = ",
         format(hpx[j + 1L], digits = 6),
         " (the derivative of log f must be non-increasing)", call. = FALSE)
  }
  invisible(TRUE)
}

## ---------------------------------------------------------------------------
## 4. Upper / lower hull evaluation
## ---------------------------------------------------------------------------

## Index of the hull segment containing each point.
ars_segment_index <- function(hull, x) {
  k <- length(hull$x)
  idx <- findInterval(x, hull$z, rightmost.closed = TRUE, all.inside = TRUE)
  pmin(pmax(idx, 1L), k)
}

## Piecewise-linear upper hull u_k(x) (tangents at the abscissae).
ars_upper_hull <- function(hull, x) {
  i <- ars_segment_index(hull, x)
  hull$hx[i] + (x - hull$x[i]) * hull$hpx[i]
}

## Piecewise-linear lower hull (squeezing function) l_k(x); -Inf outside the
## range of the abscissae.
ars_lower_hull <- function(hull, x) {
  xs <- hull$x; hs <- hull$hx
  k <- length(xs)
  out <- rep(-Inf, length(x))
  inside <- x >= xs[1L] & x <= xs[k]
  if (any(inside)) {
    xi <- x[inside]
    j <- findInterval(xi, xs, rightmost.closed = TRUE, all.inside = TRUE)
    out[inside] <- ((xs[j + 1L] - xi) * hs[j] + (xi - xs[j]) * hs[j + 1L]) /
                   (xs[j + 1L] - xs[j])
  }
  out
}

## ---------------------------------------------------------------------------
## 5. Sampling from the upper hull (piecewise exponential)
## ---------------------------------------------------------------------------

## log(sum(exp(v))) computed stably.
ars_log_sum_exp <- function(v) {
  m <- max(v)
  if (!is.finite(m)) return(m)
  m + log(sum(exp(v - m)))
}

## Log mass of every segment of exp(u_k), stored in the hull.
ars_segment_weights <- function(hull) {
  x <- hull$x; hx <- hull$hx; m <- hull$hpx; z <- hull$z
  k <- length(x)
  a <- z[seq_len(k)]          # left  end of each segment
  b <- z[seq_len(k) + 1L]     # right end of each segment
  logw <- numeric(k)

  for (i in seq_len(k)) {
    mi <- m[i]; ai <- a[i]; bi <- b[i]
    base <- hx[i] - mi * x[i]                       # u(t) = base + mi * t
    if (abs(mi) < 1e-10) {
      logw[i] <- if (is.finite(bi - ai)) base + log(bi - ai) else Inf
    } else if (mi > 0) {
      if (!is.finite(bi)) { logw[i] <- Inf } else {
        d <- if (is.finite(ai)) mi * (ai - bi) else -Inf
        logw[i] <- base + mi * bi + log1p(-exp(d)) - log(mi)
      }
    } else {
      if (!is.finite(ai)) { logw[i] <- Inf } else {
        d <- if (is.finite(bi)) mi * (bi - ai) else -Inf
        logw[i] <- base + mi * ai + log1p(-exp(d)) - log(-mi)
      }
    }
  }

  if (any(!is.finite(logw) & logw > 0))
    stop("the upper hull has infinite mass: the density is not log-concave on ",
         "this domain, or the starting points do not bracket the mode", call. = FALSE)
  logw[is.na(logw)] <- -Inf
  hull$logw <- logw
  hull$log_total <- ars_log_sum_exp(logw)
  hull
}

## Draw `n` points from the normalised upper hull exp(u_k)/integral.
ars_sample_upper <- function(hull, n) {
  k <- length(hull$x)
  p <- exp(hull$logw - hull$log_total)
  p[!is.finite(p) | p < 0] <- 0
  if (sum(p) <= 0) stop("degenerate upper hull; cannot sample", call. = FALSE)
  p <- p / sum(p)

  i <- sample.int(k, size = n, replace = TRUE, prob = p)
  u <- runif(n)
  a <- hull$z[i]; b <- hull$z[i + 1L]; m <- hull$hpx[i]

  out <- numeric(n)
  flat <- abs(m) < 1e-10
  if (any(flat)) out[flat] <- a[flat] + u[flat] * (b[flat] - a[flat])

  pos <- !flat & m > 0
  if (any(pos)) {
    d <- ifelse(is.finite(a[pos]), m[pos] * (a[pos] - b[pos]), -Inf)
    out[pos] <- b[pos] + log(u[pos] + (1 - u[pos]) * exp(d)) / m[pos]
  }
  neg <- !flat & m < 0
  if (any(neg)) {
    d <- ifelse(is.finite(b[neg]), m[neg] * (b[neg] - a[neg]), -Inf)
    out[neg] <- a[neg] + log((1 - u[neg]) + u[neg] * exp(d)) / m[neg]
  }

  ## keep strictly inside the domain (guards against round-off at the ends)
  lo <- hull$domain[1L]; hi <- hull$domain[2L]
  out[out < lo] <- lo
  out[out > hi] <- hi
  out
}

## ---------------------------------------------------------------------------
## 6. Initialisation of the starting abscissae
## ---------------------------------------------------------------------------

## Find a point inside the domain where the log density is finite.
ars_find_finite_point <- function(h, domain) {
  lo <- domain[1L]; hi <- domain[2L]
  cand <- if (is.finite(lo) && is.finite(hi)) {
    lo + (hi - lo) * c(0.5, 0.25, 0.75, 0.1, 0.9, 0.01, 0.99)
  } else if (is.finite(lo)) {
    lo + c(0.5, 1, 2, 5, 0.1, 10, 50, 1e-3)
  } else if (is.finite(hi)) {
    hi - c(0.5, 1, 2, 5, 0.1, 10, 50, 1e-3)
  } else {
    c(0, 1, -1, 5, -5, 20, -20, 100, -100)
  }
  for (x0 in cand) {
    v <- suppressWarnings(h(x0))
    if (is.finite(v)) return(x0)
  }
  stop("could not find a point inside `domain` where the density is positive and finite",
       call. = FALSE)
}

## Step outwards until the derivative of h has the required sign (needed only
## when the corresponding end of the domain is unbounded).
ars_search_slope <- function(h, domain, x0, direction, max_steps = 200L) {
  lo <- domain[1L]; hi <- domain[2L]
  step <- max(1, abs(x0) * 0.1)
  x <- x0
  for (i in seq_len(max_steps)) {
    d <- ars_derivative(h, x, domain)
    if (is.finite(d) && is.finite(h(x)) && direction * d > 0) return(x)
    x <- x + direction * step
    if (x <= lo || x >= hi) return(NA_real_)
    step <- step * 1.5
  }
  NA_real_
}

## Build a valid set of initial abscissae for the given domain.
ars_initial_points <- function(h, domain, n_init = 4L) {
  lo <- domain[1L]; hi <- domain[2L]
  x0 <- ars_find_finite_point(h, domain)

  pts <- x0
  if (!is.finite(lo)) {
    xl <- ars_search_slope(h, domain, x0, direction = -1)
    if (!is.finite(xl))
      stop("could not find a starting point with positive log-density slope on the ",
           "unbounded left tail; the density may not be log-concave or may be improper",
           call. = FALSE)
    pts <- c(pts, xl)
  } else {
    width <- if (is.finite(hi)) (hi - lo) else max(1, abs(x0 - lo))
    pts <- c(pts, lo + 0.02 * width, lo + 0.2 * width)
  }

  if (!is.finite(hi)) {
    xr <- ars_search_slope(h, domain, x0, direction = 1)
    if (!is.finite(xr))
      stop("could not find a starting point with negative log-density slope on the ",
           "unbounded right tail; the density may not be log-concave or may be improper",
           call. = FALSE)
    pts <- c(pts, xr)
  } else {
    width <- if (is.finite(lo)) (hi - lo) else max(1, abs(hi - x0))
    pts <- c(pts, hi - 0.02 * width, hi - 0.2 * width)
  }

  pts <- sort(unique(pts))
  ## add interior points to make the initial hull tighter
  if (length(pts) >= 2L && n_init > length(pts)) {
    pts <- sort(unique(c(pts, (head(pts, -1) + tail(pts, -1)) / 2)))
  }
  keep <- is.finite(suppressWarnings(h(pts))) & pts > lo & pts < hi
  pts <- pts[keep]
  if (length(pts) < 2L)
    stop("could not initialise the sampler: fewer than two usable starting points",
         call. = FALSE)
  pts
}

## ---------------------------------------------------------------------------
## 7. The main sampler
## ---------------------------------------------------------------------------

#' Adaptive rejection sampling (Gilks & Wild 1992)
#'
#' @param density_function (possibly unnormalised) density, vectorised; a
#'   function, a function name, or an expression in `x`.
#' @param domain length-2 numeric vector giving the support, e.g. c(0, Inf).
#' @param n number of samples to generate (positive integer).
#' @param ... further arguments passed to `density_function` (e.g. mean, sd).
#' @param max_points maximum number of abscissae kept in the hull.
#' @param verbose print progress information.
#' @return numeric vector of length `n` with independent draws from the density.
ars <- function(density_function, domain = c(-Inf, Inf), n = 100, ...,
                max_points = 200L, verbose = FALSE) {

  chk <- ars_validate_inputs(density_function, domain, n)
  domain <- chk$domain
  n <- chk$n

  dens <- ars_as_density(density_function, ...)
  h <- ars_make_log_density(dens)

  ## quick sanity check that the density is vectorised and non-negative
  probe <- ars_find_finite_point(h, domain)
  invisible(h(c(probe, probe)))

  hull <- ars_build_hull(h, ars_initial_points(h, domain), domain)

  samples <- numeric(n)
  n_accept <- 0L
  n_draw <- 0L
  n_eval <- 0L
  iter <- 0L
  max_iter <- 10000L

  while (n_accept < n) {
    iter <- iter + 1L
    if (iter > max_iter)
      stop("adaptive rejection sampling failed to converge after ", max_iter,
           " iterations; acceptance rate is essentially zero", call. = FALSE)

    rate <- if (n_draw > 0L) max(n_accept / n_draw, 0.05) else 0.5
    batch <- max(20L, min(as.integer(ceiling((n - n_accept) / rate * 1.2)), 20000L))

    xs <- ars_sample_upper(hull, batch)
    n_draw <- n_draw + batch

    ux <- ars_upper_hull(hull, xs)
    lx <- ars_lower_hull(hull, xs)
    w  <- runif(batch)

    ## --- squeezing test (no density evaluation needed) ---
    squeeze <- w <= exp(lx - ux)
    accepted <- xs[squeeze]

    ## --- rejection test for the remaining candidates ---
    need <- which(!squeeze)
    new_pts <- numeric(0)
    if (length(need) > 0L) {
      xr <- xs[need]
      hr <- h(xr)
      n_eval <- n_eval + length(xr)

      ## log-concavity check: h must never exceed the tangent upper hull
      tol <- 1e-6 * pmax(1, abs(ux[need]))
      viol <- which(is.finite(hr) & hr > ux[need] + tol)
      if (length(viol) > 0L) {
        j <- viol[which.max(hr[viol] - ux[need][viol])]
        stop("the supplied density is not log-concave: log f(",
             format(xr[j], digits = 6), ") = ", format(hr[j], digits = 6),
             " exceeds the tangent upper hull value ",
             format(ux[need][j], digits = 6), call. = FALSE)
      }

      ok <- is.finite(hr) & (w[need] <= exp(hr - ux[need]))
      accepted <- c(accepted, xr[ok])
      new_pts <- xr[is.finite(hr)]
    }

    if (length(accepted) > 0L) {
      take <- min(length(accepted), n - n_accept)
      samples[(n_accept + 1L):(n_accept + take)] <- accepted[seq_len(take)]
      n_accept <- n_accept + take
    }

    ## --- adaptation: enrich the hull with the evaluated points ---
    if (n_accept < n && length(new_pts) > 0L && length(hull$x) < max_points) {
      room <- max_points - length(hull$x)
      if (length(new_pts) > room) new_pts <- sample(new_pts, room)
      if (length(new_pts) > 10L) new_pts <- sample(new_pts, 10L)
      hpn <- ars_derivative(h, new_pts, domain)
      hn  <- h(new_pts)
      keep <- is.finite(hpn) & is.finite(hn)
      if (any(keep)) {
        hull <- ars_build_hull(h,
                               c(hull$x, new_pts[keep]), domain,
                               hx  = c(hull$hx, hn[keep]),
                               hpx = c(hull$hpx, hpn[keep]))
      }
    }

    if (verbose)
      message(sprintf("iter %d: accepted %d/%d, hull points %d, density evals %d",
                      iter, n_accept, n, length(hull$x), n_eval))
  }

  if (verbose)
    message(sprintf("done: acceptance rate %.3f, %d density evaluations, %d hull points",
                    n / n_draw, n_eval, length(hull$x)))

  samples
}


##############################################################################
## 8. Formal test suite
##############################################################################

## Internal helper: report the outcome of one test.
ars_report <- function(name, passed, detail = "") {
  cat(sprintf("%s: %s%s\n", name, if (passed) "PASS" else "FAIL",
              if (nzchar(detail)) paste0("  [", detail, "]") else ""))
  invisible(passed)
}

## Compare a sample with a known distribution: mean, sd and a
## Kolmogorov-Smirnov goodness-of-fit test against the true cdf.
ars_check_distribution <- function(name, samples, true_mean, true_sd, cdf,
                                   tol_mean = NULL, tol_sd = NULL, alpha = 0.001) {
  n <- length(samples)
  m <- mean(samples); s <- sd(samples)
  if (is.null(tol_mean)) tol_mean <- 4 * true_sd / sqrt(n) + 1e-8
  if (is.null(tol_sd))   tol_sd   <- 0.10 * true_sd + 1e-8

  ks <- suppressWarnings(stats::ks.test(samples, cdf))
  ok_mean <- abs(m - true_mean) < tol_mean
  ok_sd   <- abs(s - true_sd) < tol_sd
  ok_ks   <- ks$p.value > alpha
  passed  <- ok_mean && ok_sd && ok_ks

  cat(sprintf("  sample mean = %.4f (true %.4f, tol %.4f)  |  sample sd = %.4f (true %.4f, tol %.4f)  |  KS D = %.4f, p = %.4f\n",
              m, true_mean, tol_mean, s, true_sd, tol_sd,
              as.numeric(ks$statistic), ks$p.value))
  ars_report(name, passed,
             sprintf("mean=%.4f sd=%.4f ks_p=%.4f", m, s, ks$p.value))
}

## Internal helper: a test that is expected to raise an error.
ars_check_error <- function(name, expr_fun, pattern = NULL) {
  res <- tryCatch({ expr_fun(); NULL }, error = function(e) conditionMessage(e))
  passed <- !is.null(res) && (is.null(pattern) || grepl(pattern, res, ignore.case = TRUE))
  cat(sprintf("  expected an error%s; got: %s\n",
              if (is.null(pattern)) "" else paste0(" matching '", pattern, "'"),
              if (is.null(res)) "no error" else gsub("\\s+", " ", res)))
  ars_report(name, passed)
}

#' Run the full test suite.  Prints "NAME: PASS" / "NAME: FAIL" lines together
#' with mean and standard deviation statistics, and writes sample files.
test <- function(n = 5000, seed = 20250729, write_files = TRUE, out_dir = "/app") {
  set.seed(seed)
  results <- logical(0)
  add <- function(x) results[[length(results) + 1L]] <<- x

  cat("========================================================\n")
  cat("Adaptive Rejection Sampling (Gilks & Wild 1992) test suite\n")
  cat(sprintf("samples per distribution: %d, seed: %d\n", n, seed))
  cat("========================================================\n\n")

  ## ---------------- distributional correctness ----------------
  cat("[1] Standard normal N(0,1) on (-Inf, Inf)\n")
  s_norm <- ars(dnorm, c(-Inf, Inf), n = n)
  add(ars_check_distribution("NORMAL_STANDARD", s_norm, 0, 1, pnorm))
  cat("\n")

  cat("[2] Normal N(5, 2^2) via extra arguments, unnormalised input allowed\n")
  s_n52 <- ars(function(x) dnorm(x, mean = 5, sd = 2) * 17.3, c(-Inf, Inf), n = n)
  add(ars_check_distribution("NORMAL_MEAN5_SD2", s_n52, 5, 2,
                             function(q) pnorm(q, 5, 2)))
  cat("\n")

  cat("[3] Exponential(rate = 1) on (0, Inf)\n")
  s_exp <- ars(function(x) dexp(x, rate = 1), c(0, Inf), n = n)
  add(ars_check_distribution("EXPONENTIAL_RATE1", s_exp, 1, 1,
                             function(q) pexp(q, 1)))
  cat("\n")

  cat("[4] Gamma(shape = 2, rate = 1) on (0, Inf)\n")
  s_gam <- ars(function(x) dgamma(x, shape = 2, rate = 1), c(0, Inf), n = n)
  add(ars_check_distribution("GAMMA_SHAPE2", s_gam, 2, sqrt(2),
                             function(q) pgamma(q, shape = 2, rate = 1)))
  cat("\n")

  cat("[5] Beta(2, 3) on the bounded domain (0, 1)\n")
  s_beta <- ars(function(x) dbeta(x, 2, 3), c(0, 1), n = n)
  add(ars_check_distribution("BETA_2_3", s_beta, 2 / 5,
                             sqrt(2 * 3 / (5^2 * 6)),
                             function(q) pbeta(q, 2, 3)))
  cat("\n")

  cat("[6] Uniform(0, 1) -- flat log density, a degenerate log-concave case\n")
  s_unif <- ars(function(x) rep(1, length(x)), c(0, 1), n = n)
  add(ars_check_distribution("UNIFORM_0_1", s_unif, 0.5, sqrt(1 / 12), punif))
  cat("\n")

  cat("[7] Truncated normal N(0,1) on [-1, 2]\n")
  s_tn <- ars(dnorm, c(-1, 2), n = n)
  Z <- pnorm(2) - pnorm(-1)
  tn_cdf <- function(q) (pnorm(q) - pnorm(-1)) / Z
  tn_mean <- (dnorm(-1) - dnorm(2)) / Z
  tn_var <- 1 + ((-1) * dnorm(-1) - 2 * dnorm(2)) / Z - tn_mean^2
  add(ars_check_distribution("TRUNCATED_NORMAL", s_tn, tn_mean, sqrt(tn_var), tn_cdf))
  cat("\n")

  cat("[8] Density given as a character expression in x\n")
  s_expr <- ars("exp(-x^2/2)", c(-Inf, Inf), n = n)
  add(ars_check_distribution("EXPRESSION_INPUT", s_expr, 0, 1, pnorm))
  cat("\n")

  ## ---------------- the samples are not uniform noise ----------------
  cat("[9] Samples are genuinely from the target, not uniform noise\n")
  p_unif <- suppressWarnings(stats::ks.test(
    s_norm, "punif", min = min(s_norm), max = max(s_norm))$p.value)
  cat(sprintf("  KS p-value of the normal sample against Uniform(min,max) = %.3g (must be < 0.01)\n",
              p_unif))
  add(ars_report("NOT_UNIFORM_NOISE", p_unif < 0.01,
                 sprintf("mean=%.4f sd=%.4f", mean(s_norm), sd(s_norm))))
  cat("\n")

  ## ---------------- auxiliary modules ----------------
  cat("[10] Auxiliary module: numerical derivative of log f\n")
  h_norm <- function(x) -x^2 / 2
  xs <- c(-2, -0.5, 0, 1.5, 3)
  d_num <- ars_derivative(h_norm, xs, c(-Inf, Inf))
  err_d <- max(abs(d_num - (-xs)))
  cat(sprintf("  max |numeric - analytic| derivative error = %.3e (tol 1e-4)\n", err_d))
  add(ars_report("MODULE_DERIVATIVE", err_d < 1e-4,
                 sprintf("mean=%.4e sd=%.4e", mean(d_num + xs), sd(d_num + xs))))
  cat("\n")

  cat("[11] Auxiliary module: tangent intersections and hull ordering\n")
  hull <- ars_build_hull(h_norm, c(-2, -0.5, 1, 2.5), c(-Inf, Inf))
  z_ok <- all(diff(hull$z) >= 0) &&
          all(hull$z[2:length(hull$x)] >= head(hull$x, -1) - 1e-8) &&
          all(hull$z[2:length(hull$x)] <= tail(hull$x, -1) + 1e-8)
  ## for N(0,1) the tangents at x_j, x_{j+1} cross at the midpoint
  z_mid <- (head(hull$x, -1) + tail(hull$x, -1)) / 2
  err_z <- max(abs(hull$z[2:length(hull$x)] - z_mid))
  cat(sprintf("  intersections sorted and bracketed: %s; max |z - analytic midpoint| = %.3e\n",
              z_ok, err_z))
  add(ars_report("MODULE_INTERSECTIONS", z_ok && err_z < 1e-6,
                 sprintf("mean=%.4f sd=%.4f", mean(hull$z[2:length(hull$x)]), sd(hull$z[2:length(hull$x)]))))
  cat("\n")

  cat("[12] Auxiliary module: squeezing -- lower hull <= log f <= upper hull\n")
  xs <- seq(-4, 4, length.out = 400)
  lo_h <- ars_lower_hull(hull, xs); up_h <- ars_upper_hull(hull, xs); tr <- h_norm(xs)
  sandwich <- all(lo_h <= tr + 1e-8) && all(tr <= up_h + 1e-8)
  gap <- mean(up_h - tr)
  cat(sprintf("  envelope holds on 400 grid points: %s; mean upper-hull gap = %.4f\n",
              sandwich, gap))
  add(ars_report("MODULE_HULL_ENVELOPE", sandwich,
                 sprintf("mean=%.4f sd=%.4f", gap, sd(up_h - tr))))
  cat("\n")

  cat("[13] Auxiliary module: sampling from the upper hull matches its own density\n")
  ## for a single tangent the hull is exactly an exponential distribution
  hull_exp <- ars_build_hull(function(x) -x, c(1, 2, 4), c(0, Inf))
  draws <- ars_sample_upper(hull_exp, 20000)
  emp <- mean(draws); dsd <- sd(draws)
  ## upper hull of exp(-x) with tangents of slope -1 is exactly Exp(1)
  ok_hullsamp <- abs(emp - 1) < 0.05 && abs(dsd - 1) < 0.08
  cat(sprintf("  upper-hull draws: mean = %.4f (true 1), sd = %.4f (true 1)\n", emp, dsd))
  add(ars_report("MODULE_UPPER_HULL_SAMPLING", ok_hullsamp,
                 sprintf("mean=%.4f sd=%.4f", emp, dsd)))
  cat("\n")

  ## ---------------- input validation ----------------
  cat("[14] Input validation\n")
  add(ars_check_error("VALIDATION_NEGATIVE_N",
                      function() ars(dnorm, c(-Inf, Inf), n = -10), "positive"))
  add(ars_check_error("VALIDATION_ZERO_N",
                      function() ars(dnorm, c(-Inf, Inf), n = 0), "positive"))
  add(ars_check_error("VALIDATION_NON_INTEGER_N",
                      function() ars(dnorm, c(-Inf, Inf), n = 10.5), "whole number"))
  add(ars_check_error("VALIDATION_BAD_DOMAIN_ORDER",
                      function() ars(dnorm, c(5, -5), n = 10), "domain"))
  add(ars_check_error("VALIDATION_DOMAIN_LENGTH",
                      function() ars(dnorm, c(0, 1, 2), n = 10), "length 2"))
  add(ars_check_error("VALIDATION_DOMAIN_NA",
                      function() ars(dnorm, c(NA, 1), n = 10), "NA"))
  add(ars_check_error("VALIDATION_BAD_DENSITY",
                      function() ars("not a density !!", c(0, 1), n = 10), NULL))
  add(ars_check_error("VALIDATION_NEGATIVE_DENSITY",
                      function() ars(function(x) -abs(x) - 1, c(0, 1), n = 10),
                      "non-negative"))
  cat("\n")

  ## ---------------- log-concavity detection ----------------
  cat("[15] Detection of non-log-concave densities\n")
  add(ars_check_error("LOGCONCAVITY_CAUCHY",
                      function() ars(function(x) dcauchy(x), c(-Inf, Inf), n = 500),
                      "log-concav|improper|slope"))
  add(ars_check_error("LOGCONCAVITY_T_DF2",
                      function() ars(function(x) dt(x, df = 2), c(-Inf, Inf), n = 500),
                      "log-concav|improper|slope"))
  add(ars_check_error("LOGCONCAVITY_BIMODAL",
                      function() ars(function(x) 0.5 * dnorm(x, -4) + 0.5 * dnorm(x, 4),
                                     c(-Inf, Inf), n = 500),
                      "log-concav"))
  add(ars_check_error("LOGCONCAVITY_LOGNORMAL",
                      function() ars(function(x) dlnorm(x), c(0, Inf), n = 500),
                      "log-concav|improper|slope|starting"))
  cat("\n")

  ## ---------------- reproducibility ----------------
  cat("[16] Reproducibility with a fixed seed\n")
  set.seed(99); a <- ars(dnorm, c(-Inf, Inf), n = 200)
  set.seed(99); b <- ars(dnorm, c(-Inf, Inf), n = 200)
  same <- identical(a, b)
  cat(sprintf("  two runs with seed 99 identical: %s\n", same))
  add(ars_report("REPRODUCIBLE_SEED", same,
                 sprintf("mean=%.4f sd=%.4f", mean(a), sd(a))))
  cat("\n")

  ## ---------------- sample files ----------------
  if (write_files) {
    cat("[17] Writing sample files\n")
    f_norm <- file.path(out_dir, "normal_samples.txt")
    f_exp  <- file.path(out_dir, "exponential_samples.txt")
    ok_write <- tryCatch({
      write.table(round(s_norm, 8), file = f_norm, row.names = FALSE,
                  col.names = FALSE)
      write.table(round(s_exp, 8), file = f_exp, row.names = FALSE,
                  col.names = FALSE)
      file.exists(f_norm) && file.exists(f_exp)
    }, error = function(e) FALSE)
    cat(sprintf("  wrote %s (%d values) and %s (%d values)\n",
                f_norm, length(s_norm), f_exp, length(s_exp)))
    add(ars_report("SAMPLE_FILES_WRITTEN", ok_write,
                   sprintf("mean=%.4f sd=%.4f", mean(s_norm), sd(s_norm))))
    cat("\n")
  }

  ## ---------------- summary ----------------
  n_pass <- sum(unlist(results)); n_all <- length(results)
  cat("========================================================\n")
  cat(sprintf("SUMMARY: %d / %d tests passed\n", n_pass, n_all))
  cat(sprintf("OVERALL: %s\n", if (n_pass == n_all) "PASS" else "FAIL"))
  cat("========================================================\n")

  invisible(list(passed = n_pass, total = n_all, all_passed = n_pass == n_all))
}

## Running `Rscript /app/ars.R` executes the test suite.
if (!interactive() && identical(environment(), globalenv()) &&
    sys.nframe() == 0L && length(commandArgs(trailingOnly = TRUE)) == 0L) {
  invisible(test())
}
